288			ownerParams.put("id", owner.getId());
289	        List<Pet> pets = owner.getPets();
290	        // cascade delete pets
291	        for (Pet pet : pets){
292	        	Map<String, Object> petParams = new HashMap<>();
293	        	petParams.put("id", pet.getId());
294	        	// cascade delete visits
295	        	List<Visit> visits = pet.getVisits();
